import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
const source=readFileSync(process.argv[2],'utf8');
const start=source.indexOf('        let recallHandledThisTurn = false;');
const end=source.indexOf('          let executed:',start);
assert(start>=0 && end>start);
const fn=new Function('result','toolHistory','toolCallLog','executed','let recallAttempted=false;'+source.slice(start,end)+'executed.push(call.callId); } return recallAttempted;');
const history=[], logs=[], executed=[];
const calls=ids=>({toolCalls:ids.map((id,i)=>({callId:id,name:i===0?'unknown':'context_archive_recall',arguments:{}}))});
assert.equal(fn(calls(['unknown','first','second','third']),history,logs,executed),true);
assert.deepEqual(executed,['first']);
assert.equal(history.filter(x=>x.type==='function_call').length,4);
assert.equal(history.filter(x=>x.type==='function_call_output' && JSON.parse(x.output).diagnostics[0].code==='parallel_recall_limit').length,2);
assert.equal(logs.length,2);
assert(logs.every(x=>x.ok===false && x.failure_code==='parallel_recall_limit'));
fn(calls(['unknown2','next']),history,logs,executed);
assert.deepEqual(executed,['first','next']);
assert(source.includes('argValue("--max-turns") ?? 8'));
assert(source.includes('at most 3 times in total'));
console.log(JSON.stringify({driven_by:'agent',actor:'codex-inline-spill-benefit-r2',checks:9,passed:true}));
